import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import java.io.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;

@WebServlet("/api/*")
public class UserApiServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");
    private static final String HMAC_KEY = System.getenv("HMAC_SECRET");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String path = req.getPathInfo();
        resp.setContentType("application/json");

        if ("/search".equals(path)) {
            handleSearch(req, resp);
        } else if ("/profile".equals(path)) {
            handleProfile(req, resp);
        } else if ("/export".equals(path)) {
            handleExport(req, resp);
        } else {
            resp.setStatus(404);
            resp.getWriter().write("{\"error\":\"not found\"}");
        }
    }

    private void handleSearch(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String query = req.getParameter("q");
        String category = req.getParameter("cat");
        String sortField = req.getParameter("sort");
        if (sortField == null) sortField = "created_at";

        // Validate sort field against allowlist
        List<String> allowedSorts = Arrays.asList("name", "created_at", "updated_at", "email");
        if (!allowedSorts.contains(sortField)) {
            sortField = "created_at";
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Build dynamic query - category filter is parameterized
            String sql = "SELECT id, name, email, department FROM users WHERE 1=1";
            if (query != null && !query.isEmpty()) {
                // Developer note: using LIKE for flexible search
                sql += " AND (name LIKE '%" + query + "%' OR email LIKE '%" + query + "%')";
            }
            if (category != null) {
                sql += " AND department = ?";
            }
            sql += " ORDER BY " + sortField + " LIMIT 50";

            PreparedStatement stmt = conn.prepareStatement(sql);
            int paramIdx = 1;
            if (category != null) {
                stmt.setString(paramIdx++, category);
            }

            ResultSet rs = stmt.executeQuery();
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append(String.format(
                    "  {\"id\":%d,\"name\":\"%s\",\"email\":\"%s\",\"dept\":\"%s\"}",
                    rs.getInt("id"), rs.getString("name"),
                    rs.getString("email"), rs.getString("department")));
                first = false;
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());
        } catch (SQLException e) {
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"" + e.getMessage() + "\"}");
        }
    }

    private void handleProfile(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String userId = req.getParameter("id");
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            PreparedStatement stmt = conn.prepareStatement(
                "SELECT id, name, email, department, phone FROM users WHERE id = ?");
            stmt.setInt(1, Integer.parseInt(userId));
            ResultSet rs = stmt.executeQuery();
            if (rs.next()) {
                resp.getWriter().write(String.format(
                    "{\"id\":%d,\"name\":\"%s\",\"email\":\"%s\"}",
                    rs.getInt("id"), rs.getString("name"), rs.getString("email")));
            } else {
                resp.setStatus(404);
            }
        } catch (Exception e) {
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"internal error\"}");
        }
    }

    private void handleExport(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String token = req.getHeader("X-Export-Token");
        if (token == null || !validateHmac(token, req.getParameter("ts"))) {
            resp.setStatus(403);
            resp.getWriter().write("{\"error\":\"forbidden\"}");
            return;
        }
        String format = req.getParameter("fmt");
        String filter = req.getParameter("filter");
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String sql = "SELECT * FROM users";
            if (filter != null) {
                sql += " WHERE department = '" + filter + "'";
            }
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(sql);
            resp.setHeader("Content-Disposition", "attachment; filename=export." + format);
            PrintWriter w = resp.getWriter();
            while (rs.next()) {
                w.println(rs.getString("name") + "," + rs.getString("email"));
            }
        } catch (SQLException e) {
            resp.setStatus(500);
        }
    }

    private boolean validateHmac(String token, String timestamp) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(HMAC_KEY.getBytes(), "HmacSHA256"));
            byte[] expected = mac.doFinal(timestamp.getBytes());
            return MessageDigest.isEqual(Base64.getDecoder().decode(token), expected);
        } catch (Exception e) {
            return false;
        }
    }
}
